                "• 1709 წელს ვახტანგ VI-მ თბილისში პირველი ქართული სტამბა დააარსა. სტამბის მოწყობაში მას ანთიმოზ ივერიელი დაეხმარა, რომელმაც თავისი მოწაფე, სტამბის ხელობის მცოდნე უნგრელ-ვლახელი მიხაილ იშტვანოვიჩი გამოგზავნა.\n• სტამბისთვის მეფის სასახლესთან, ანჩისხატისა და სიონის ტაძრებს შორის, სპეციალური შენობა ააგეს.\n• აქ დაიბეჭდა პირველი ქართული წიგნები: „სახარება“, „ვეფხისტყაოსანი“, 2 სასწავლო სახელმძღვანელო და 11 სასულიერო წიგნი. „სახარების“ ერთი ცალი ვახტანგმა ოქროს ყდაში ჩასვა და საჩუქრად ანთიმოზს გაუგზავნა.\n• ბეჭდვას სამეცნიერო მუშაობა უძღოდა წინ: ქართულ და უცხო ხელნაწერებს ერთმანეთს ადარებდნენ და ტექსტს აზუსტებდნენ. „ვეფხისტყაოსნის“ ტექსტი თავად ვახტანგმა გამართა და ბოლოსიტყვაობა დაურთო, რომელშიც მისი გამოცემის აუცილებლობას ასაბუთებდა.",
