                "• ვახტანგ VI-ის ინიციატივით, ბერი ეგნატაშვილის მეთაურობით შეიქმნა „სწავლულ კაცთა კომისია“. მას „ქართლის ცხოვრების“ რედაქტირება, გამართვა და გაგრძელება დაევალა.\n• კომისიის მინაწერის მიხედვით, საქართველო „ჟამთა ვითარებისგან“ აოხრებული იყო და მატიანე აღარ იწერებოდა. ვახტანგმა შეკრიბა მეცნიერი კაცები და მოაძიებინა „ქართლის ცხოვრების“ ნუსხები, მცხეთის, გელათისა და სხვა ეკლესიებისა და დიდებულების სიგელ-გუჯრები, სომხური და სპარსული მატიანეები.\n• კომისიამ XIV–XVII საუკუნეების საქართველოს ისტორია აღწერა და „ქართლის ცხოვრებაში“ შეიტანა. შევსებულ კრებულს „ახალი ქართლის ცხოვრება“ უწოდეს.\n• XVIII საუკუნის დასაწყისისთვის ქართულ ენაში უამრავი სპარსული და თურქული სიტყვა იყო. ენის გასაწმენდად და მისი ნორმების დასადგენად სულხან-საბა ორბელიანმა ქართული ლექსიკონი შეადგინა და 1716 წელს დაასრულა. საბას ლექსიკონი ენციკლოპედიური ხასიათისაა — მასში ისტორიული და გეოგრაფიული სახელებიც არის განმარტებული.",
