                "• 1711 წელს ირანში „გურჯისტანის ვალის“ თანამდებობა თავისუფალი აღმოჩნდა და შაჰის არჩევანი ვახტანგზე შეჩერდა. 1712 წელს ქართლის ჯანიშინი ტახტზე დასამტკიცებლად ისპაჰანში გაემგზავრა. მის ამალაში მეფის გამზრდელი, სულხან-საბა ორბელიანიც იყო.\n• შაჰმა ვახტანგს გამუსლიმება მოსთხოვა, მაგრამ ვახტანგმა სარწმუნოების შეცვლაზე უარი თქვა. ის დაატყვევეს, ქართლი კი მის გამუსლიმებულ ძმას, იესე ალი-ყული-ხანს, გადასცეს.\n• ქართველებმა ვახტანგის დაბრუნება ევროპის დახმარებით სცადეს. ფრანგი მისიონერის, ჟან რიშარის, ხელშეწყობით სულხან-საბა ევროპაში გაემგზავრა. მან იმოგზაურა საფრანგეთსა და იტალიაში (1713–1716) და ესტუმრა საფრანგეთის მეფე ლუი XIV-სა და რომის პაპ კლიმენტ XI-ს.\n• საბა საფრანგეთის მინისტრს, გრაფ დე პონშატრენს, 1714 წელს წერდა: თუ ვახტანგი ისპაჰანში დარჩება, საქართველოს გამუსლიმების საფრთხე ემუქრება; თუ დაბრუნდება, ქართველები ქრისტიანობას შეინარჩუნებენ და, მეფის მაგალითით, კათოლიკეებს შეუერთდებიან.",
