                "• XVII საუკუნის ბოლოს რუსეთი ვრცელი, მაგრამ ფეოდალური სახელმწიფო იყო და განვითარებით დასავლეთ ევროპას მნიშვნელოვნად ჩამორჩებოდა.\n• 1682 წელს ტახტზე ახალგაზრდა და ენერგიული მეფე პეტრე I ავიდა. ის რომანოვების დინასტიიდან იყო — რომანოვები რუსეთს 1613–1917 წლებში მართავდნენ.\n• რუსეთს ზღვაზე გასასვლელი არ ჰქონდა, ეკონომიკის განვითარებისთვის კი ის აუცილებელი იყო. 1695 წელს პეტრე I სამხრეთით, აზოვის ზღვის სანაპიროზე, ოსმალეთის ციხესიმაგრის ასაღებად გაილაშქრა.\n• ლაშქრობა წარუმატებლად დასრულდა: რუსებს ფლოტი არ ჰყავდათ, ჯარი კი სავალალო მდგომარეობაში იყო — ცუდად შეიარაღებული, ცუდად გაწვრთნილი. პეტრე მიხვდა, რომ ძლიერი ფლოტი და ჯარის გარდაქმნა სჭირდებოდა.",
