                "• ვითარება მხოლოდ 1640 წელს შეიცვალა: შოტლანდიასთან ომის გამო მეფეს ისევ ფული დასჭირდა და პარლამენტი მოიწვია. ეს პარლამენტი 1640–1653 წლებში მუშაობდა — ამიტომ „ხანგრძლივი პარლამენტი“ ეწოდა.\n• დეპუტატების უმრავლესობა მეფის მიმართ არაკეთილგანწყობილი იყო. მათ მიიღეს 204-მუხლიანი დოკუმენტი მეფის პოლიტიკის კრიტიკით, გააუქმეს უკანონო გადასახადები და კანონები, აკრძალეს პარლამენტის დათხოვნა მისი თანხმობის გარეშე.\n• პარლამენტი მეფეზე კონტროლის დაწესებას და მინისტრების დანიშვნის უფლების მოპოვებას ცდილობდა.\n• მეფის მომხრეები — ძირითადად უმაღლესი არისტოკრატია — „კავალრები“ იყვნენ და ძველ წესრიგს იცავდნენ. წვრილი მემამულეები კი პარლამენტის გაძლიერებას უჭერდნენ მხარს; მათ სათავეში ოლივერ კრომველი ჩაუდგა.\n• დაპირისპირება ისე გამწვავდა, რომ მეფე თავის მომხრეებთან ერთად ლონდონიდან იორკში გადავიდა.",
