                "• სამოქალაქო ომის დროს ინგლისში რამდენიმე პოლიტიკური ძალა ჩამოყალიბდა. ისინი ხან ერთიანდებოდნენ, ხან ერთმანეთს ედავებოდნენ — ეკლესიისა და სახელმწიფოს ურთიერთობაზე, წოდებრივი პრივილეგიების გაუქმებაზე, მიწების განაწილებასა და საარჩევნო უფლებაზე.\n• პარლამენტის არმიის „სახალხო შეთანხმება“ (1647) მოითხოვდა: პარლამენტში ადგილები მოსახლეობის რაოდენობის მიხედვით განაწილდეს; არჩეული წარმომადგენელი მხოლოდ ამომრჩეველს ემორჩილება და წყვეტს კანონებს, ომსა და მშვიდობას.\n• იქვე ეწერა: კანონის შესრულება ყველას თანაბარი ვალდებულებაა — არც ქონება, არც წარმოშობა და არც თანამდებობა არავის ათავისუფლებს კანონისგან.\n• კრომველის თანამებრძოლი, გენერალი ჰენრი აირტონი, არ ეთანხმებოდა: მისი აზრით, სახელმწიფოს მართვის უფლება მხოლოდ მას აქვს, ვისაც ქვეყანაში „მუდმივი და მტკიცე დაინტერესება“ — მიწის საკუთრება — აქვს.",
