                "• ფრანგი ფილოსოფოსის, ფიზიკოსისა და მათემატიკოსის, რენე დეკარტის ცნობილი ფრაზაა: „ვაზროვნებ, მაშასადამე, ვარსებობ“. მისთვის გონება იყო შემეცნების მთავარი საშუალება და ადამიანის ქცევის განმსაზღვრელი.\n• ვოლტერის (1694–1778) აზრით, უკეთეს საზოგადოებაში ადამიანებს რელიგიური აღმსარებლობისა და სიტყვის თავისუფლება უნდა ჰქონდეთ და ყველა წოდების ადამიანი თანასწორი უნდა იყოს. იდეალური მმართველი, მისი აზრით, ფილოსოფოსი იქნებოდა.\n• ჟან-ჟაკ რუსო (1712–1778) თვლიდა, რომ ცივილიზაციამ ადამიანები დაამახინჯა. მისი იდეალი ბუნებითი კანონებით ცხოვრება იყო — თანასწორობა ყველაფერში, ქონებრივი თანასწორობაც, კერძო საკუთრების გაუქმებით.\n• რუსო საზოგადოებრივ შეთანხმებას და ხალხის დამოუკიდებელ მმართველობას ემხრობოდა. საზოგადოების საკეთილდღეოდ ხალხს რევოლუციაც შეეძლო — მაგრამ მხოლოდ უკიდურეს შემთხვევაში, რადგან რევოლუციას უბედურებად მიიჩნევდა.",
