                "• განმანათლებლობის იდეების მიმდევარი იყო გიორგი XII-ის ძე, ტახტის მემკვიდრე დავით ბატონიშვილიც. ზოგი მკვლევრის აზრით, რუსი მოხელეები მას ეჭვით უყურებდნენ, რადგან საფრანგეთის რევოლუციის იდეებითა და რეფორმების სურვილით იყო გატაცებული.\n• 1800 წელს დავითმა შეადგინა სამართლის კრებული „სამართალი ბატონიშვილისა დავითისა“ — მასში ფრანგი ენციკლოპედისტების გავლენა ჩანს.\n• გიორგი XII-ს შვილის გატაცება აღელვებდა: ვოლტერის სწავლებას „ურჯულოს“ უწოდებდა და ამბობდა, რომ დავითის მიერ რუსეთიდან ჩამოტანილი ვოლტერის პორტრეტი ცეცხლში დაწვა.\n• 1803 წელს დავითი ბაგრატიონთა სამეფო ოჯახის სხვა წევრებთან ერთად პეტერბურგში გადაასახლეს. იქ მან ქართულად თარგმნა და განმარტებები დაურთო მონტესკიეს „კანონთა გონს“ და დაწერა მხატვრული ნაწარმოები „ახალი შიხი“, რომელსაც ვოლტერისა და რუსოს გავლენა ეტყობა.\n• იაკობ გოგებაშვილი წერდა, რომ ქართველებისთვის საფრანგეთის რევოლუცია უცნობი არ იყო და ზოგი მათგანი რესპუბლიკური მმართველობის დიდი პატივისმცემელიც იყო.",
