                "• ნაპოლეონ ბონაპარტი (1769–1821) კუნძულ კორსიკიდან იყო. სამხედრო სასწავლებელი დაამთავრა და 1785 წლიდან საფრანგეთის არმიაში მსახურობდა. რევოლუციას აღფრთოვანებით შეხვდა.\n• 1793 წელს ის ქალაქ ტულონის ალყაში მონაწილეობდა: ტულონი მონარქიის მომხრეებმა აიღეს, რესპუბლიკელებმა კი ქალაქი ნაპოლეონის გეგმით დაიბრუნეს. ამისთვის 24 წლის კაპიტანს გენერლობა უბოძეს.\n• 1795 წელს პარიზში მონარქისტთა აჯანყების ჩახშობის შემდეგ ნაპოლეონი პარიზის გარნიზონის მეთაურად დანიშნეს. 1796 წელს ის იტალიაში მებრძოლი არმიის მთავარსარდალი გახდა და წარმატებას მიაღწია, 1798 წელს კი ეგვიპტეშიც წარმატებით ილაშქრა.\n• 1800 წლის წერილში ნაპოლეონი წერდა, რომ რესპუბლიკის განმტკიცება სურს, მაგრამ დიდ სახელმწიფოში რესპუბლიკური მმართველობის შენარჩუნება შეუძლებლად მიაჩნია — საფრანგეთს „შერეული ტიპის რესპუბლიკა“ სჭირდებაო. საზოგადოებრივ აზრს შმაგ ცხენს ადარებდა, რომლის შეკავებასაც ცდილობდა.",
