                "• ხელისუფლებაში მოსვლისთანავე ნაპოლეონმა რეფორმები დაიწყო. სამართალი მოუწესრიგებელი იყო: მოქმედებდა რევოლუციამდელი კანონებიც და რევოლუციის შემდეგ მიღებულიც, რომლებიც ერთმანეთს არ შეესაბამებოდა. ნაპოლეონმა კანონებზე სამუშაოდ კომისია მოიწვია; 1804 წელს სახელმწიფო საბჭომ სამოქალაქო კოდექსი დაამტკიცა.\n• კოდექსის მიხედვით, „ყველა ფრანგი სარგებლობს სამოქალაქო სამართლით“. კოდექსი საერო ქორწინებას აკანონებდა. ოჯახში უპირატესობა კვლავ კაცს ჰქონდა, თუმცა ზოგ მუხლში ცოლ-ქმრის თანასწორობა იყო ხაზგასმული.\n• კოდექსი კერძო საკუთრებას უძრავ და მოძრავ ქონებად ყოფდა. საკუთრების შეძენა და გადაცემა ანდერძით ან ჩუქებით შეიძლებოდა — მემკვიდრეობის ფეოდალურ წესებს კოდექსი აღარ ცნობდა.\n• ნაპოლეონის კოდექსი ახალი დროის პირველი სამოქალაქო კოდექსი იყო. მან რევოლუციის მონაპოვარი დაამკვიდრა: მოქალაქის თავისუფლება, პროფესიის არჩევისა და სინდისის თავისუფლება, სახელმწიფოს საერო ხასიათი, კანონის უზენაესობა და მის წინაშე ყველას თანასწორობა.",
