                "• საფრანგეთის რევოლუციამ ძალიან შეაშფოთა ავსტრიის იმპერატორი და პრუსიის მეფე. მათ სურდათ, საფრანგეთიდან რევოლუციური იდეების გავრცელებისთვის ხელი შეეშალათ. ამას მათ საფრანგეთიდან გაქცეული ემიგრანტებიც ურჩევდნენ, რომლებმაც მეზობელ გერმანულ სახელმწიფოებს შეაფარეს თავი. ფრანგებსა და გერმანელებს სასაზღვრო მიწებზეც ჰქონდათ დავა.\n• 1792 წელს საფრანგეთმა თავად გამოუცხადა ომი ავსტრიას. ავსტრიამ და პრუსიამ კავშირი შეკრეს, რომელსაც სხვა გერმანული სამეფოებიც შეუერთდნენ.\n• მოკავშირეთა დაახლოებით 250 ათასი ჯარისკაცი მდინარე რაინზე გადავიდა. ისინი იმედოვნებდნენ, რომ რევოლუციის მოწინააღმდეგე ფრანგები მათ მიემხრობოდნენ.\n• მოხდა პირიქით: ყველა, ვისაც იარაღის აღება შეეძლო, საბრძოლველად გამოვიდა — ორ თვეში საფრანგეთის არმია უკვე 400 ათას კაცს ითვლიდა.",
