                "• კონტინენტურმა ბლოკადამ მიზანს ვერ მიაღწია: საფრანგეთის მოკავშირეები, მათ შორის რუსეთიც, ბლოკადის წესებს არღვევდნენ და ინგლისთან ფარულად ვაჭრობდნენ.\n• ნაპოლეონმა რუსეთზე ლაშქრობა გადაწყვიტა და 1810 წლის ბოლოდან სამზადისს შეუდგა. მის დიდ არმიაში ფრანგების გარდა დამორჩილებული და მოკავშირე ქვეყნების ჯარებიც შედიოდა — 600 ათასამდე ჯარისკაცი და 1372 ზარბაზანი.\n• მისი მიზანი მოსკოვის აღება და იმის მიღწევა იყო, რომ ალექსანდრე I-ს დამარცხება ეღიარებინა.\n• ნაპოლეონს აღმოსავლეთში ლაშქრობის იდეაც ჰქონდა. თანამებრძოლთან საუბარში ის ამბობდა: თუ მოსკოვი აღებული იქნება და რუსეთი დამარცხდება, ვერავინ შეაჩერებს ტიფლისიდან (თბილისიდან) განგისკენ დაძრულ ფრანგულ ჯარს — ასე კი ინდოეთის ვაჭრობა დაინგრევა, რომელსაც ინგლისის ძლიერება ეყრდნობა.",
