                "• ვენის კონგრესის გადაწყვეტილებით ბელგია ნიდერლანდების სამეფოში შედიოდა. ნიდერლანდელებისგან განსხვავებით, ბელგიელები კათოლიკები იყვნენ და ფრანგულად ლაპარაკობდნენ.\n• ბელგიელები დიდი მღელვარებით ადევნებდნენ თვალს საფრანგეთის ამბებს. 1830 წლის აგვისტოს ბოლოს ბელგიაში საყოველთაო გამოსვლები დაიწყო და ხალხმა თავისუფლება და დამოუკიდებლობა მოითხოვა.\n• ნიდერლანდების მეფემ ვილჰელმ I-მა ჯერ მოლაპარაკება სცადა, უშედეგოდ; შემდეგ აჯანყებულებს ჯარი დაუპირისპირა, მაგრამ აჯანყებულებმა გაიმარჯვეს და დროებითი მთავრობა შექმნეს.\n• ვილჰელმ I-მა დახმარებისთვის დიდ სახელმწიფოებს მიმართა. ინგლისის, ავსტრიის, პრუსიის, რუსეთისა და საფრანგეთის წარმომადგენლები ლონდონში შეიკრიბნენ და ერთთვიანი მსჯელობის შემდეგ ბელგია დამოუკიდებელ სახელმწიფოდ ცნეს.",
