                "• ქართლ-კახეთის სამეფოს გაუქმების შემდეგ აღმოსავლეთ საქართველოში რუსული მმართველობა დამყარდა. რუსეთის იმპერია გუბერნიებად იყოფოდა, რომლებსაც გუბერნატორები და გენერალ-გუბერნატორები განაგებდნენ. ქართლ-კახეთის ახალ მმართველობას რუსეთის მთავრობამ „საქართველოს მმართველობა“ უწოდა.\n• მის სათავეში „საქართველოს მთავარსარდალი“, იგივე მთავარმართებელი, იდგა — სამხედრო მოხელე, რომელიც იმპერიის წინაშე ჯერ ქართლ-კახეთის, შემდეგ კი მთელი სამხრეთ კავკასიის საქმეებზე აგებდა პასუხს. სამოქალაქო საქმეებს მისი თანაშემწე, „საქართველოს მმართველი“, განაგებდა.\n• რუსმა მოხელეებმა ქართული არ იცოდნენ, ამიტომ განყოფილებებში მრჩევლებად ქართველ თავადებსაც ნიშნავდნენ — ისინი მოხელეებს ხალხთან აკავშირებდნენ.\n• ქვეყანა მაზრებად დაიყო; მაზრას სამხედრო მოხელე მართავდა. ქალაქის მმართველი — კომენდანტი — რუსი ოფიცერი იყო, მისი თანაშემწე, პოლიცმაისტერი, კი ქართველი თავადაზნაურობიდან ინიშნებოდა.\n• ახალი ხელისუფლება ქვეყანაში ჩამდგარ რუსეთის რეგულარულ ჯარს ეყრდნობოდა. სახელმწიფო გადასახადად პური დააწესეს — მთავრობას ჯარის გამოსაკვებად, პირველ რიგში, პური სჭირდებოდა.",
