                "• რუსული მმართველობის დამყარების შემდეგ ალექსანდრე I-მა ბაგრატიონები საქართველოდან გაასახლა. პეტერბურგში მათ კარგ პირობებს უქმნიდნენ — მხოლოდ სამშობლოში დაბრუნება ეკრძალებოდათ. მაგრამ მოსახლეობის უკმაყოფილება არ ცხრებოდა: სახელმწიფოებრიობის დაკარგვას ეკონომიკური და სოციალური მიზეზებიც ემატებოდა.\n• ამიტომ ხელისუფლებამ 1840–1841 წლებში რამდენიმე რეფორმა გაატარა. სამხრეთ კავკასია ორ დიდ ადმინისტრაციულ ერთეულად — საქართველო-იმერეთის გუბერნიად და კასპიის ოლქად — დაიყო.\n• 1840 წლიდან თბილისს საქალაქო მმართველობა ჰქონდა: ქალაქის თავი და ექვსი ხმოსანი (წარმომადგენელი). ქალაქის თავს მთელი მოსახლეობა ირჩევდა, ხმოსნებს კი — უძრავი ქონების მფლობელები, ვაჭრები და ხელოსნები (თითო ჯგუფი — ორ-ორს). მათი უფლებები ძალიან შეზღუდული იყო: ქალაქის კეთილმოწყობა, გადასახადების დროულად აკრეფა, ხელოსნობისა და მეურნეობის ხელშეწყობა.\n• მოგვიანებით მართლმსაჯულებაც შეცვალეს: სამოქალაქო საქმეების განხილვა ადგილობრივი ადათ-წესების მიხედვითაც გახდა შესაძლებელი.",
