                "• 1802 წელს თბილისში ვაჟთა პირველი ორკლასიანი სასწავლებელი გაიხსნა. სწავლა მხოლოდ რუსულად მიმდინარეობდა, რუსული კი ძალიან ცოტამ იცოდა, ამიტომ სასწავლებელი მალე დაიხურა.\n• ორი წლის შემდეგ „კეთილშობილთა სასწავლებელი“ გაიხსნა, სადაც უკვე ქართულად და რუსულად ასწავლიდნენ. 1830 წელს ის გიმნაზიად გადაკეთდა და მალე ქართული ენის შეზღუდვაც დაიწყო. დიდხანს ეს საქართველოში ერთადერთი საერო სკოლა იყო; ის გოლოვინის (დღევანდელ რუსთაველის) გამზირზე, მეფისნაცვლის სასახლის გვერდით მდებარეობდა.\n• სასკოლო ქსელის გაფართოება ვორონცოვის სახელს უკავშირდება: თბილისსა და ქუთაისში წმინდა ნინოს სახელობის ქალთა სასწავლებლები და გიმნაზიები გაიხსნა.\n• მეფისნაცვალმა ქართული თეატრის აღდგენის ნებართვაც გასცა. 1850 წლის 2 (14) იანვარს თბილისის გიმნაზიის სცენაზე დაიდგა ამავე სკოლის ყოფილი მოსწავლის, გიორგი ერისთავის, პიესა „გაყრა“ — 14 იანვარს დღესაც ქართული თეატრის დღედ აღნიშნავენ. 1851 წელს კი თბილისის ქარვასლის თეატრში პირველი საოპერო წარმოდგენა გაიმართა.\n• 1852 წელს ვორონცოვის დახმარებით ქართული ჟურნალი „ცისკარი“ გამოიცა.",
