                "• 1852 წელს თბილისში რუსეთის საიმპერატორო გეოგრაფიული საზოგადოების კავკასიის განყოფილების მუზეუმი დაარსდა, რომლის ბაზაზეც შემდეგ კავკასიის მუზეუმი ჩამოყალიბდა. მისი დირექტორი იყო გერმანელი მეცნიერი — გეოგრაფი, ბოტანიკოსი და ეთნოლოგი — გუსტავ რადე (1831–1903). მან თავისი კოლექციები მუზეუმს გადასცა და საზოგადოებისთვის ხელმისაწვდომი გახადა.\n• 1847 წელს ვორონცოვმა პოეტსა და საზოგადო მოღვაწეს, ვახტანგ ორბელიანს, სთხოვა, საკუთარი სახსრებით აეგო შენობა საჯარო ბიბლიოთეკისთვის. ორბელიანი დათანხმდა და 1851 წელს შენობა ბიბლიოთეკას გადაეცა. 1852 წლიდან კავკასიაში დაბეჭდილი ყველა გამოცემის ორი ეგზემპლარი ბიბლიოთეკას უნდა გადასცემოდა.\n• ბოტანიკური ბაღის ადგილას ძველად ქართველ მეფეთა „ციხის ბაღი“ იყო — მის შესახებ პირველ ცნობებს ფრანგი მოგზაური ჟან შარდენი გვაწვდის. 1845 წელს ვორონცოვის ბრძანებით მას „თბილისის ბოტანიკური ბაღი“ ეწოდა.\n• ვორონცოვი ქართული კულტურის შესწავლასაც უწყობდა ხელს: ძეგლების რესტავრაციას, ძველი ტექსტების გამოცემას. მისი დავალებით დიმიტრი მეღვინეთუხუცესიშვილი საქართველოს სიძველეებს აღწერდა; 1852 წელს უფლისციხეში არქეოლოგიური გათხრები დაიწყო.",
