              title: "თბილისი ერეკლე II-ის დროს",
              paragraphs: [
                "• XVIII–XIX საუკუნეების თბილისი ბევრმა მოგზაურმა აღწერა. მათი ჩანაწერების შედარებით ჩანს, როგორ შეიცვალა ქალაქი რუსული მმართველობის დამყარების შემდეგ.\n• გერმანელი მეცნიერი იოჰან გიულდენშტედტი თბილისში ერეკლე II-ის დროს, 1771–1772 წლებში, იყო. მისი აღწერით, ქალაქი თითქმის სამკუთხედის ფორმისა იყო და აგურის კედლით იყო შემოზღუდული; აღმოსავლეთ კუთხეში ციხე ნარიყალა იდგა, დასავლეთში — სიმაგრე შარდახტი. ქალაქს სახელი თბილი წყაროების და მათთან აშენებული აბანოების გამო ჰქონდა.\n• თბილისში დაახლოებით 20 000 კაცი ცხოვრობდა. ქუჩები დაახლოებით ორი მეტრის სიგანისა იყო, შესახვევები — კიდევ უფრო ვიწრო. სახლები ერთსართულიანი, აგურით ნაგები იყო, ბრტყელი, თიხით დაფენილი სახურავებით; ფანჯრებში შუშის ნაცვლად გაქონილი ქაღალდი ეკრა. წყლის საწრეტები არ ჰქონდა, ქუჩებში ნაგავი იყრებოდა, ამიტომ ეპიდემიები ხშირი იყო.\n• რუსეთის იმპერატორის წარგზავნილი იაკობ რაინეგსი წერდა, რომ ქალაქი მტკვრის მარჯვენა ნაპირზე იდგა და გარეუბნებთან ერთად დაახლოებით ოთხი ათასი, უმეტესად ღარიბული სახლი ჰქონდა. მარცხენა ნაპირზე მდებარე ავლაბარი და მეტეხი თბილისს ხიდით უკავშირდებოდა. ისინი დიდხანს დანგრეული იყო — მხოლოდ 1780 წელს დაიწყო ერეკლემ მათი ხელახლა გაშენება. ქალაქი ცოცხალ ვაჭრობას ეწეოდა.",
              ],
