                "• რუსი პოეტი ალექსანდრე პუშკინი თბილისს ერზრუმისკენ მოგზაურობისას, 1829 წელს, ეწვია. ქალაქი მას ხალხმრავალი მოეჩვენა: ვიწრო და დაკლაკნილ ქუჩებში კალათებგადაკიდებული ვირები დარბოდნენ, ხარშებმული ურმები გზას ღობავდნენ.\n• მოედანზე შეკრებილ სომხებს, ქართველებს, ჩერქეზებსა და სპარსელებს შორის ყარაბაღულ ცხენებზე ამხედრებული ახალგაზრდა რუსები დასეირნობდნენ.\n• პუშკინი თბილისის გოგირდის აბანოებით აღფრთოვანდა. მისი აღწერით, ქალაქის დიდი ნაწილი „აზიურად“ იყო ნაგები — დაბალი სახლები, ბრტყელი სახურავები, — ჩრდილოეთ ნაწილში კი უკვე ევროპული არქიტექტურა და სწორი მოედნები იყო.\n• ბაზარი რიგებად იყო დაყოფილი; თურქული და სპარსული საქონელი იაფი იყო, თბილისური იარაღი კი მთელ აღმოსავლეთში ძვირად ფასობდა.",
