                "• კავკასიის ომში ჩრდილოეთ კავკასიის მთიელებზე რუსეთის გამარჯვების აღსანიშნავად თბილისში საკათედრო ტაძარი აიგო. ის შუა საუკუნეების რუსი მხედართმთავრისა და წმინდანის, ალექსანდრე ნეველის, სახელობისა იყო.\n• ტაძარი ალექსანდრეს ბაღის ზედა ნაწილში, მოედანზე იდგა, რომელსაც მოგვიანებით სობორნი (რუსულად — „ტაძრის“) მოედანი ეწოდა; მოსახლეობა ტაძარს „სობოროს“ ეძახდა. ეს ნეობიზანტიური სტილის ნაგებობა იყო.\n• ასე, მოგზაურების აღწერებიდან და შენობებიდან ჩანს, როგორ შეიცვალა თბილისი: ძველი, „აზიური“ ქალაქის — ვიწრო ქუჩების, ბაზრების, აბანოების — გვერდით გაჩნდა ევროპული არქიტექტურის რუსული უბანი სახელმწიფო დაწესებულებებით, სამხედრო ნაგებობები, გერმანელთა კოლონია, თეატრი. არქიტექტურაც ისტორიული წყაროა — ის გვიყვება, ვინ და როგორ მართავდა ქალაქს.",
