                alt: "აშშ-ის აღმოსავლეთი ნაწილის რუკა: ცისფრად — კავშირის შტატები, ოხრისფრად — კავშირის ერთგული მონათმფლობელური შტატები (დელავერი, მერილენდი, კენტუკი, მისური, დასავლეთ ვირჯინია), მოწითალოდ — კონფედერაციის 11 შტატი; დედაქალაქები ვაშინგტონი და რიჩმონდი; ჯვრებით — ფორტ სამტერი (1861), გეტისბერგი და ვიქსბერგი (1863), ატლანტა (1864), აპომატოქსი (1865); ისრით — შერმანის ლაშქრობა ატლანტიდან სავანამდე (1864); წყვეტილი ხაზით — კავშირის ფლოტის ბლოკადა და მისურის კომპრომისის ხაზი 36°30′ (1820). შტატების საზღვრები დღევანდელია.",
