                "• ჩრდილოეთ კავკასიაში მრავალი ხალხი ცხოვრობდა — ადიღეელები (ჩერქეზები), ყაბარდოელები, ოსები, ჩეჩნები, ინგუშები, დაღესტნის ხალხები. ისინი ენით, კულტურითა და წეს-ჩვეულებებით განსხვავდებოდნენ და ერთიანი სახელმწიფო არ ჰქონიათ.\n• მთიანი რელიეფი ქალაქებისა და გზების განვითარებას ხელს უშლიდა; დასახლებები ციხე-სიმაგრეებითა და კოშკებით იყო გამაგრებული. ერთადერთი ძველი ქალაქი და ნავსადგური დარუბანდი (დერბენტი) იყო.\n• სამხრეთ კავკასიის დაპყრობის შემდეგ რუსეთს ჩრდილოეთ კავკასიის მთიანეთის დამორჩილება სჭირდებოდა: მთიელები იმპერიასა და მის ახალ სამფლობელოებს შორის გზებს — მათ შორის საქართველოს სამხედრო გზას — ემუქრებოდნენ.\n• 1817 წლიდან გენერალმა ალექსეი ერმოლოვმა მთიელების წინააღმდეგ სისტემური ომი დაიწყო: ციხე-სიმაგრეების ხაზები ააშენა, ურჩ სოფლებს ანადგურებდა და მოსახლეობას დაბლობზე ასახლებდა. 1817–1864 წლების ომს ისტორიოგრაფიაში კავკასიის ომს უწოდებენ.",
