              fact: "მუჰაჯირობა არაბული სიტყვიდან „ჰიჯრა“ (გადასახლება) მომდინარეობს და მუსლიმების მასობრივ გადასახლებას ნიშნავს იქიდან, სადაც ისინი უმცირესობაში აღმოჩნდნენ, მუსლიმურ სახელმწიფოში.",
